CREATE TABLE remediation_plans (tenant_id text NOT NULL,id text NOT NULL,incident_id text NOT NULL,payload jsonb NOT NULL,plan_hash text NOT NULL,state text NOT NULL DEFAULT 'PROPOSED',created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,approved_by text,approved_hash text,approval_expires_at timestamptz,revoked boolean NOT NULL DEFAULT false,execution_key text,lease text,lease_expires_at timestamptz,executed_at timestamptz,verified_at timestamptz,outcome text,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,execution_key));
CREATE TABLE remediation_outbox (tenant_id text NOT NULL,plan_id text NOT NULL,state text NOT NULL DEFAULT 'PENDING',attempts int NOT NULL DEFAULT 0,lease text,PRIMARY KEY(tenant_id,plan_id));
CREATE TABLE replay_resources (tenant_id text NOT NULL,run_id text NOT NULL,version int NOT NULL DEFAULT 0,disk_percent double precision NOT NULL,observed_at timestamptz NOT NULL DEFAULT now(),source_mode text NOT NULL DEFAULT 'SIMULATED',PRIMARY KEY(tenant_id,run_id));
CREATE TABLE remediation_effects (tenant_id text NOT NULL,plan_id text NOT NULL,plan_hash text NOT NULL,run_id text NOT NULL,resource_version int NOT NULL,disk_percent double precision NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,plan_id));
CREATE TABLE remediation_samples (tenant_id text NOT NULL,id text NOT NULL,run_id text NOT NULL,resource_version int NOT NULL,disk_percent double precision NOT NULL,observed_at timestamptz NOT NULL DEFAULT now(),source_mode text NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE INDEX remediation_sample_scope ON remediation_samples(tenant_id,run_id,observed_at DESC);
CREATE TABLE remediation_postmortems (tenant_id text NOT NULL,plan_id text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,plan_id));
